int tempo = 0;
std::vector<int> disc(n, -1), fim(n, -1);

void dfs(int u, int pai) {
    disc[u] = ++tempo;
    for (int v : adj[u]) {
        if (v == pai) continue;      // não volta pela mesma aresta ao pai
        if (disc[v] == -1) {
            dfs(v, u);                // aresta de árvore
        }
        // disc[v] != -1 e v != pai: aresta de retorno (back edge)
    }
    fim[u] = ++tempo;
}

std::vector<int> dist(n, INF);
std::priority_queue<std::pair<int,int>,
                     std::vector<std::pair<int,int>>,
                     std::greater<>> pq;   // (distância, vértice)
dist[s] = 0;
pq.push({0, s});
while (!pq.empty()) {
    auto [d, u] = pq.top(); pq.pop();
    if (d > dist[u]) continue;        // entrada obsoleta, já superada
    for (auto [v, peso] : adj[u]) {
        if (dist[u] + peso < dist[v]) {
            dist[v] = dist[u] + peso;
            pq.push({dist[v], v});
        }
    }
}

int tempo = 0;
std::vector<int> disc(n, -1), low(n, -1);
std::vector<std::pair<int,int>> pontes;

void dfs(int u, int pai) {
    disc[u] = low[u] = ++tempo;
    for (int v : adj[u]) {
        if (v == pai) continue;
        if (disc[v] == -1) {
            dfs(v, u);
            low[u] = std::min(low[u], low[v]);
            if (low[v] > disc[u])
                pontes.push_back({u, v});      // condição de ponte
        } else {
            low[u] = std::min(low[u], disc[v]); // aresta de retorno
        }
    }
}

std::vector<int> dist(n, INF);
std::deque<int> dq;
dist[s] = 0;
dq.push_front(s);
while (!dq.empty()) {
    int u = dq.front(); dq.pop_front();
    for (auto [v, peso] : adj[u]) {   // peso é 0 ou 1
        if (dist[u] + peso < dist[v]) {
            dist[v] = dist[u] + peso;
            if (peso == 0) dq.push_front(v);
            else            dq.push_back(v);
        }
    }
}
